const staticData = $getWorkflowStaticData('global');

const input = $input.first().json;

const updates =
  Array.isArray(input.result)
    ? input.result
    : Array.isArray(input.body?.result)
      ? input.body.result
      : [];

const previousLastUpdateId = Number(staticData.last_update_id || 0);

if (!updates.length) {
  return [];
}

let maxUpdateId = previousLastUpdateId;

const output = [];

for (const update of updates) {
  const updateId = Number(update.update_id || 0);

  if (!updateId || updateId <= previousLastUpdateId) {
    continue;
  }

  if (updateId > maxUpdateId) {
    maxUpdateId = updateId;
  }

  const msg = update.message || update.edited_message || {};
  const text = String(msg.text || '').trim();

  if (!text) {
    continue;
  }

  const chatId = msg.chat?.id;
  const userId = msg.from?.id;

  if (!chatId || !userId) {
    continue;
  }

  output.push({
    json: {
      update_id: updateId,
      chat_id: chatId,
      user_id: userId,
      username: msg.from?.username || '',
      first_name: msg.from?.first_name || '',
      telegram_message_id: msg.message_id,
      user_question: text,
      question: text,
      created_at: new Date().toISOString()
    }
  });
}

// ВАЖНО: обновляем last_update_id сразу в Parse node
if (maxUpdateId > previousLastUpdateId) {
  staticData.last_update_id = maxUpdateId;
}

return output;

const runId = `telegram_polling_${new Date().toISOString().replace(/[:.]/g, '-')}`;

return $input.all().map(item => ({
  json: {
    ...item.json,
    run_id: runId
  }
}));

const inputItems = $input.all();

const unsafePatterns = [
// Прямое сокрытие или занижение доходов
/(?:скрыть|скрывать|спрятать|прятать|утаить|утаивать|занизить|занижать)[\s\S]{0,60}(?:доход\w*|выручк\w*|плат[её]ж\w*|оплат\w*|поступлени\w*)/iu,

// Намеренное неотражение доходов или отдельных платежей
/не\s+(?:показывать|отражать|указывать|вносить|регистрировать|декларировать)[\s\S]{0,60}(?:доход\w*|выручк\w*|плат[её]ж\w*|оплат\w*|поступлени\w*)/iu,

// Обратный порядок слов: «доход не показывать»
/(?:доход\w*|выручк\w*|плат[её]ж\w*|оплат\w*|поступлени\w*)[\s\S]{0,60}не\s+(?:показывать|отражать|указывать|вносить|регистрировать|декларировать)/iu,

// Уклонение и обход налогов
/(?:обойти|обходить|уклониться|уклоняться)[\s\S]{0,60}(?:налог\w*|уплат\w*|запрет\w*|ограничени\w*|правил\w*)/iu,

// Намеренная неуплата налога
/как[\s\S]{0,30}(?<![А-Яа-яЁёA-Za-z])не\s+платить[\s\S]{0,30}налог\w*/iu,

// Намеренное неформирование чека
/(?:не\s+формировать|не\s+выдавать|не\s+пробивать|не\s+создавать)[\s\S]{0,40}чек\w*/iu,

// Поддельные и фиктивные чеки
/(?:фиктивн\w*|поддельн\w*|фальшив\w*|ложн\w*)[\s\S]{0,30}чек\w*/iu,

/(?:сделать|создать|сформировать|подделать)[\s\S]{0,40}(?:фиктивн\w*|поддельн\w*|фальшив\w*|ложн\w*)[\s\S]{0,20}чек\w*/iu,

// Запрос схемы сокрытия или обхода
/(?:схем\w*|способ\w*)[\s\S]{0,50}(?:скрыт\w*|уклонени\w*|обход\w*|неуплат\w*)/iu
];

// Запросы об исправлении уже совершённой ошибки.
// Они не блокируются как попытка уклонения.
const correctionPatterns = [
/(?:что\s+делать|как\s+исправить|как\s+устранить)[\s\S]{0,80}(?:случайн\w*|по\s+ошибк\w*|ошибочн\w*|забыл\w*|не\s+успел\w*|пропустил\w*)[\s\S]{0,80}(?:не\s+отразил\w*|не\s+указал\w*|не\s+вн[её]с\w*|не\s+сформировал\w*|доход\w*|плат[её]ж\w*|чек\w*)/iu,

/(?:случайн\w*|по\s+ошибк\w*|ошибочн\w*|забыл\w*|не\s+успел\w*|пропустил\w*)[\s\S]{0,80}(?:не\s+отразил\w*|не\s+указал\w*|не\s+вн[её]с\w*|не\s+сформировал\w*)[\s\S]{0,80}(?:что\s+делать|как\s+исправить|как\s+устранить)/iu
];

