route: 'blocked',
answer: 'Вопрос пустой. Укажите вопрос по налогу на профессиональный доход.',
sources: [],
safety_reason: 'empty_question'
}
};
}

const isCorrectionRequest = correctionPatterns.some((pattern) =>
pattern.test(question)
);

const isUnsafe =
!isCorrectionRequest &&
unsafePatterns.some((pattern) => pattern.test(question));

if (isUnsafe) {
return {
json: {
