function normalizeQdrantResponse(json) {
  // Нормальный JSON от Qdrant
  if (json?.result) {
    return json;
  }

  if (json?.body?.result) {
    return json.body;
  }

  if (json?.data?.result) {
    return json.data;
  }

  // Если body/data — строка JSON
  if (typeof json?.body === 'string') {
    const parsed = tryParseJson(json.body);
    if (parsed?.result) return parsed;
  }

  if (typeof json?.data === 'string') {
    const parsed = tryParseJson(json.data);
    if (parsed?.result) return parsed;
  }

  // Если пришёл stream/buffer от n8n
