  if (bytes.length > 0) {
    const text = bytesToText(bytes);
    const parsed = tryParseJson(text);

    if (parsed?.result) {
      return parsed;
    }

    throw new Error(`Could not parse Qdrant buffer. Text preview: ${text.slice(0, 500)}`);
