const responseItems = $input.all();
const originalItems = $('Build retrieved context').all();

const FALLBACK =
'В базе знаний нет достаточной информации для ответа на этот вопрос.';

function normalizeText(value) {
return String(value || '').trim();
}

function cleanAnswer(rawAnswer) {
const answer = normalizeText(rawAnswer);
const lowerAnswer = answer.toLowerCase();

const fallbackBeginnings = [
'в базе знаний нет достаточной информации',
'в базе знаний недостаточно информации',
'нет достаточной информации для ответа',
'по базе знаний невозможно однозначно ответить'
];

const isFallback = fallbackBeginnings.some(function (beginning) {
return lowerAnswer.startsWith(beginning);
});

if (isFallback) {
return {
answer: FALLBACK,
isFallback: true
};
}

return {
answer: answer,
isFallback: false
};
}

function isValidIdentifier(value) {
const text = normalizeText(value);

if (!text) {
return false;
}

for (const char of text) {
const isLatinLetter =
(char >= 'a' && char <= 'z') ||
(char >= 'A' && char <= 'Z');

const isDigit =
  char >= '0' && char <= '9';

const isAllowedSymbol =
  char === '_' || char === '-';

if (
  !isLatinLetter &&
  !isDigit &&
  !isAllowedSymbol
) {
  return false;
}

}

return true;
}

function extractCitations(answer) {
const text = normalizeText(answer);
const citations = [];

let searchPosition = 0;

while (searchPosition < text.length) {
const openingBracket = text.indexOf(
'[',
searchPosition
);

if (openingBracket === -1) {
  break;
}

const closingBracket = text.indexOf(
  ']',
  openingBracket + 1
);

if (closingBracket === -1) {
  break;
}

const fullMatch = text.slice(
  openingBracket,
  closingBracket + 1
);

const inside = text
  .slice(openingBracket + 1, closingBracket)
  .trim();

const separatorPosition = inside.indexOf('/');

if (separatorPosition !== -1) {
  const docId = inside
    .slice(0, separatorPosition)
    .trim();

  const chunkId = inside
    .slice(separatorPosition + 1)
    .trim();

  if (
    isValidIdentifier(docId) &&
    isValidIdentifier(chunkId)
  ) {
    citations.push({
      fullMatch: fullMatch,
      doc_id: docId,
      chunk_id: chunkId
    });
  }
}

searchPosition = closingBracket + 1;

}

return citations;
}

function sourceKey(docId, chunkId) {
return (
normalizeText(docId) +
'::' +
normalizeText(chunkId)
);
}

function isForbiddenSource(docId) {
const normalized = normalizeText(
docId
).toLowerCase();

if (!normalized.startsWith('npd_')) {
return true;
}

if (normalized.startsWith('wiki_')) {
return true;
}

if (
normalized === 'glossary' ||
normalized === 'fallback_rules' ||
normalized === 'negative_scenarios'
) {
return true;
}

return false;
}

function normalizeCitation(citation) {
const docId = normalizeText(
citation && citation.doc_id
);

let chunkId = normalizeText(
citation && citation.chunk_id
);

/*

Модель иногда сокращает полный chunk_id:


chunk_004


вместо:


npd_employment_combination_v1_chunk_004


Восстанавливаем полный идентификатор,
но затем обязательно проверяем его по RAW sources.
*/
if (
docId &&
chunkId.toLowerCase().startsWith('chunk_')
) {
chunkId = docId + '_' + chunkId;
}

return {
fullMatch: citation.fullMatch,
doc_id: docId,
chunk_id: chunkId
};
}

function getModelAnswer(response) {
if (
response &&
response.choices &&
response.choices[0] &&
response.choices[0].message
) {
return normalizeText(
response.choices[0].message.content
);
}

if (
response &&
response.body &&
response.body.choices &&
response.body.choices[0] &&
response.body.choices[0].message
) {
return normalizeText(
response.body.choices[0].message.content
);
}

if (
response &&
response.data &&
response.data.choices &&
response.data.choices[0] &&
response.data.choices[0].message
) {
return normalizeText(
response.data.choices[0].message.content
);
}

return '';
}

function getUsage(response) {
if (response && response.usage) {
return response.usage;
}

if (
response &&
response.body &&
response.body.usage
) {
return response.body.usage;
}

if (
response &&
response.data &&
response.data.usage
) {
return response.data.usage;
}

return {};
}

function getModelName(response) {
if (response && response.model) {
return response.model;
}

if (
response &&
response.body &&
response.body.model
) {
return response.body.model;
}

if (
response &&
response.data &&
response.data.model
) {
return response.data.model;
}

return '';
}

return responseItems.map(function (item, index) {
const response = item.json || {};

const originalItem = originalItems[index];
const original = originalItem
? originalItem.json
: null;

if (!original) {
throw new Error(
'Build retrieved context output not found for item ' +
index
);
}

const rawAnswer = getModelAnswer(response);
const cleaned = cleanAnswer(rawAnswer);
const usage = getUsage(response);

const rawSources = Array.isArray(
original.sources
)
? original.sources
: [];

const allowedSources = rawSources.filter(
function (source) {
return Boolean(
source &&
source.doc_id &&
source.chunk_id &&
!isForbiddenSource(source.doc_id)
);
}
);

const allowedSourceKeys = new Set(
allowedSources.map(function (source) {
return sourceKey(
source.doc_id,
source.chunk_id
);
})
);

let answer = cleaned.answer;
let isFallback = cleaned.isFallback;

const extractedCitations = isFallback
? []
: extractCitations(answer);

const normalizedCitations =
extractedCitations.map(function (citation) {
return normalizeCitation(citation);
});

const invalidCitations =
normalizedCitations.filter(
function (citation) {
if (
isForbiddenSource(citation.doc_id)
) {
return true;
}

    const key = sourceKey(
      citation.doc_id,
      citation.chunk_id
    );

    return !allowedSourceKeys.has(key);
  }
);

const hasMissingCitations =
  !isFallback &&
  normalizedCitations.length === 0;

const hasInvalidCitations =
  invalidCitations.length > 0 ||
  hasMissingCitations;

if (hasInvalidCitations) {
answer = FALLBACK;
isFallback = true;
}

let citations = [];

if (isFallback) {
answer = FALLBACK;
citations = [];
} else {
citations = normalizedCitations;

/*
 * Заменяем сокращённые ссылки внутри текста ответа
 * на проверенные полные идентификаторы.
 */
for (const citation of citations) {
  const canonicalCitation =
    '[' +
    citation.doc_id +
    ' / ' +
    citation.chunk_id +
    ']';

  if (
    citation.fullMatch &&
    citation.fullMatch !== canonicalCitation
  ) {
    answer = answer.split(
      citation.fullMatch
    ).join(canonicalCitation);
  }
}

}

const verifiedSources = citations
.map(function (citation) {
return allowedSources.find(
function (source) {
return (
sourceKey(
source.doc_id,
source.chunk_id
) ===
sourceKey(
citation.doc_id,
citation.chunk_id
)
);
}
);
})
.filter(Boolean);

/*

Удаляем дубли источников, если модель
сослалась на один чанк несколько раз.
*/
const uniqueVerifiedSources = [];
const uniqueVerifiedKeys = new Set();

for (const source of verifiedSources) {
const key = sourceKey(
source.doc_id,
source.chunk_id
);

if (!uniqueVerifiedKeys.has(key)) {
  uniqueVerifiedKeys.add(key);
  uniqueVerifiedSources.push(source);
}

}

const uniqueCitations = [];
const uniqueCitationKeys = new Set();

for (const citation of citations) {
const key = sourceKey(
citation.doc_id,
citation.chunk_id
);

if (!uniqueCitationKeys.has(key)) {
  uniqueCitationKeys.add(key);
  uniqueCitations.push(citation);
}

}

const sourcesInAnswer = uniqueCitations
.map(function (citation) {
return (
citation.doc_id +
' / ' +
citation.chunk_id
);
})
.join(',');

return {
json: {
...original,

  run_id:
    original.run_id ||
    (
      'telegram_polling_' +
      new Date()
        .toISOString()
        .slice(0, 10)
    ),

  timestamp: new Date().toISOString(),

  retrieved_doc_ids:
    original.retrieved_doc_ids || '',

  top_score:
    original.top_score || '',

  qdrant_result_count:
    original.qdrant_result_count || 0,

  has_context:
    original.has_context === true,

  answer: answer,

  telegram_answer: answer,

  sources_in_answer:
    isFallback
      ? ''
      : sourcesInAnswer,

  sources:
    isFallback
      ? []
      : uniqueVerifiedSources,

  model: getModelName(response),

  prompt_tokens:
    usage.prompt_tokens || 0,

  completion_tokens:
    usage.completion_tokens || 0,

  total_tokens:
    usage.total_tokens || 0,

  status:
    isFallback
      ? 'fallback'
      : 'answered',

  full_fallback_detected:
    isFallback,

  source_verification_passed:
    !hasInvalidCitations,

  invalid_sources_detected:
  hasMissingCitations
    ? [
        {
          reason: 'missing_valid_citation'
        }
      ]
    : invalidCitations.map(
        function (citation) {
          return {
            doc_id: citation.doc_id,
            chunk_id: citation.chunk_id
          };
        }
      )
}

};
});

const staticData = $getWorkflowStaticData('global');

const lastUpdateId = Number(staticData.last_update_id || 0);
const offset = lastUpdateId > 0 ? lastUpdateId + 1 : undefined;

return [
  {
    json: {
      telegram_offset: offset,
      telegram_limit: 10
    }
  }
];

const LIMIT = 20;
const staticData = $getWorkflowStaticData('global');

if (!staticData.dailyUsage) {
  staticData.dailyUsage = {};
}

const items = $input.all();
const result = [];

for (const item of items) {
  const userId = String(item.json.user_id || '');
  const question = String(item.json.user_question || '').trim();

  if (!userId) {
    result.push({
      json: {
        ...item.json,
        limit_exceeded: true,
        telegram_answer: 'Не удалось определить пользователя.'
      }
    });
    continue;
  }

  // Служебные команды пока не расходуют лимит
  const isServiceCommand = ['/reset']
  .includes(question.toLowerCase());

  // Дневной лимит считается по московскому времени.
const currentDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Moscow',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());
  const usageKey = `${userId}:${currentDate}`;

  const used = Number(staticData.dailyUsage[usageKey] || 0);

  if (isServiceCommand) {
    result.push({
      json: {
        ...item.json,
        limit_exceeded: false,
        is_service_command: true,
        requests_used: used,
        requests_left: Math.max(LIMIT - used, 0)
      }
