const staticData = $getWorkflowStaticData('global');

if (!staticData.dialogues) {
  staticData.dialogues = {};
}

const MAX_MESSAGES = 6;
const MEMORY_TTL_HOURS = 24;
const now = Date.now();

return $input.all().map(item => {
  const chatId = String(item.json.chat_id || '');
  const userId = String(item.json.user_id || '');

  const dialogueKey = `${chatId}:${userId}`;

  const storedHistory = Array.isArray(staticData.dialogues[dialogueKey])
    ? staticData.dialogues[dialogueKey]
    : [];

  // Оставляем только сообщения не старше 24 часов
  const validHistory = storedHistory.filter(message => {
    const timestamp = new Date(message.timestamp || 0).getTime();

    return (
      Number.isFinite(timestamp) &&
      now - timestamp <= MEMORY_TTL_HOURS * 60 * 60 * 1000
    );
  });

  // Сохраняем очищенную историю обратно
  staticData.dialogues[dialogueKey] = validHistory.slice(-MAX_MESSAGES);

  return {
    json: {
      ...item.json,
      dialogue_key: dialogueKey,
      dialogue_history: validHistory.slice(-MAX_MESSAGES),
      has_dialogue_history: validHistory.length > 0
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const originalQuestion = String(
    item.json.user_question || item.json.question || ''
  ).trim();

  const question = originalQuestion.toLowerCase();

  const hasHistory =
    item.json.has_dialogue_history === true ||
    item.json.has_dialogue_history === 'true';

  const words = question
    .replace(/[?!.,;:()[\]"«»]/g, ' ')
    .split(/\s+/)
    .filter((word) => word.length > 0);

  /*
   * Для русского текста не используем \b.
   * Конец слова проверяем через (?=\s|$|[?!.,;:])
   */
  const end = '(?=\\s|$|[?!.,;:])';

  const followUpStarts = [
    new RegExp(`^а\\s+если${end}`, 'u'),
    new RegExp(`^а\\s+как${end}`, 'u'),
    new RegExp(`^а\\s+кто${end}`, 'u'),
    new RegExp(`^а\\s+почему${end}`, 'u'),
    new RegExp(`^а\\s+что${end}`, 'u'),
    new RegExp(`^а\\s+можно${end}`, 'u'),
    new RegExp(`^а\\s+тогда${end}`, 'u'),
    new RegExp(`^и\\s+что${end}`, 'u'),
    new RegExp(`^и\\s+как${end}`, 'u'),
    new RegExp(`^но\\s+если${end}`, 'u'),
    new RegExp(`^тогда${end}`, 'u'),
    new RegExp(`^то\\s+есть${end}`, 'u')
  ];

  const contextReferencePatterns = [
    /(^|[\s?!.,;:])это(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])этот(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])эта(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])эти(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])этого(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])этому(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])так(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])такой(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])такое(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])тогда(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])там(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])он(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])она(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])они(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])его(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])её(?=$|[\s?!.,;:])/u,
    /(^|[\s?!.,;:])их(?=$|[\s?!.,;:])/u,
    /с\s+этим/u,
    /в\s+этом\s+случае/u,
    /в\s+таком\s+случае/u
  ];

  const shortFollowUps = [
    /^почему[?!.,]*$/u,
    /^зачем[?!.,]*$/u,
    /^как[?!.,]*$/u,
    /^кто[?!.,]*$/u,
    /^когда[?!.,]*$/u,
    /^где[?!.,]*$/u,
    /^что\s+делать[?!.,]*$/u,
    /^что\s+тогда[?!.,]*$/u,
    /^и\s+что[?!.,]*$/u,
    /^а\s+дальше[?!.,]*$/u,
    /^можно\s+подробнее[?!.,]*$/u,
    /^объясни\s+подробнее[?!.,]*$/u
  ];

  const startsAsFollowUp = followUpStarts.some((pattern) =>
    pattern.test(question)
  );

  const refersToContext = contextReferencePatterns.some((pattern) =>
    pattern.test(question)
  );

  const isExplicitShortFollowUp = shortFollowUps.some((pattern) =>
    pattern.test(question)
  );

  const isShortContextualQuestion =
    words.length <= 6 && refersToContext;

  const needsHistory =
    hasHistory &&
    (
      startsAsFollowUp ||
      isExplicitShortFollowUp ||
      isShortContextualQuestion
    );

  return {
    json: {
      ...item.json,
      needs_history: needsHistory,
      search_question: originalQuestion,
      answer_question: originalQuestion,
      search_query: originalQuestion,
      follow_up_detection: {
        has_history: hasHistory,
        starts_as_follow_up: startsAsFollowUp,
        refers_to_context: refersToContext,
        explicit_short_follow_up: isExplicitShortFollowUp,
        short_contextual_question: isShortContextualQuestion,
        word_count: words.length
      }
    }
  };
});

