const source = $('Detect follow-up question').first().json;
const response = $input.first().json;

const rawContent =
  response.choices?.[0]?.message?.content || '{}';

let parsed = {};

try {
  parsed = JSON.parse(rawContent);
} catch (error) {
  parsed = {};
}

const answerQuestion = String(
  parsed.answer_question || source.user_question || ''
).trim();

const searchQuery = String(
  parsed.search_query ||
  parsed.answer_question ||
  source.user_question ||
  ''
).trim();

return [
  {
    json: {
      ...source,

      answer_question: answerQuestion,
      search_query: searchQuery,

      // Оставим для совместимости со старыми узлами
      search_question: searchQuery,

      question_was_rewritten:
        Boolean(parsed.answer_question || parsed.search_query),

      rewrite_raw_response: rawContent
    }
  }
];

const staticData = $getWorkflowStaticData('global');

if (!staticData.dialogues) {
  staticData.dialogues = {};
}

return $input.all().map(item => {
  const question = String(
    item.json.user_question ||
    item.json.question ||
    ''
  ).trim();

  const chatId = String(item.json.chat_id || '');
  const userId = String(item.json.user_id || '');

  const isResetCommand =
    /^\/reset(?:@\w+)?$/i.test(question);

  if (!isResetCommand) {
    return {
      json: {
        ...item.json,
        service_handled: false
      }
    };
  }

  const dialogueKey = `${chatId}:${userId}`;

  const previousMessages = Array.isArray(
    staticData.dialogues[dialogueKey]
  )
    ? staticData.dialogues[dialogueKey].length
    : 0;

  delete staticData.dialogues[dialogueKey];

  return {
    json: {
      ...item.json,
      dialogue_key: dialogueKey,
      dialogue_history: [],
      has_dialogue_history: false,
      service_handled: true,
      service_command: 'reset',
      cleared_messages: previousMessages,
      answer: 'История диалога очищена. Можете начать новую тему.',
      telegram_answer: 'История диалога очищена. Можете начать новую тему.',
      status: 'service_command',
      sources: []
    }
  };
});

const staticData = $getWorkflowStaticData('global');

if (!staticData.dialogues) {
  staticData.dialogues = {};
}

const MAX_MESSAGES = 6;
const MAX_USER_LENGTH = 700;
const MAX_ASSISTANT_LENGTH = 1800;

return $input.all().map(item => {
  const chatId = String(item.json.chat_id || '');
  const userId = String(item.json.user_id || '');

  const userQuestion = String(
    item.json.user_question ||
    item.json.question ||
    ''
  ).trim();

  const assistantAnswer = String(
    item.json.telegram_answer ||
    item.json.answer ||
    ''
  ).trim();

  if (!chatId || !userId || !userQuestion || !assistantAnswer) {
    return {
      json: {
        ...item.json,
        memory_saved: false,
        memory_error:
          'Не хватает chat_id, user_id, user_question или ответа'
      }
    };
  }

  const dialogueKey =
    item.json.dialogue_key || `${chatId}:${userId}`;

  const history = Array.isArray(staticData.dialogues[dialogueKey])
    ? staticData.dialogues[dialogueKey]
    : [];

  const timestamp = new Date().toISOString();

  history.push({
    role: 'user',
    content: userQuestion.slice(0, MAX_USER_LENGTH),
    timestamp
  });

  history.push({
    role: 'assistant',
    content: assistantAnswer.slice(0, MAX_ASSISTANT_LENGTH),
    timestamp
  });

  staticData.dialogues[dialogueKey] = history.slice(-MAX_MESSAGES);

  return {
    json: {
      ...item.json,
      dialogue_key: dialogueKey,
      memory_saved: true,
      dialogue_memory_size:
        staticData.dialogues[dialogueKey].length
    }
  };
});
